    assertInstanceOf(UntypedObject.class, locationProperties.get("address"));
    assertInstanceOf(UntypedString.class, // creates untyped string
    (locationProperties.get("displayName")));
    assertInstanceOf(UntypedDouble.class, // creates untyped number
    (locationProperties.get("floorCount")));
    assertInstanceOf(UntypedBoolean.class, // creates untyped boolean
    locationProperties.get("hasReception"));
    assertInstanceOf(UntypedNull.class, // creates untyped null
    locationProperties.get("contact"));
    assertInstanceOf(UntypedObject.class, // creates untyped null
    locationProperties.get("coordinates"));
    var coordinates = (UntypedObject) locationProperties.get("coordinates");
    var coordinatesProperties = coordinates.getValue();
    assertInstanceOf(UntypedDouble.class, // creates untyped decimal
    coordinatesProperties.get("latitude"));
    assertInstanceOf(UntypedDouble.class, coordinatesProperties.get("longitude"));
    assertEquals("Microsoft Building 92", ((UntypedString) locationProperties.get("displayName")).getValue());
    assertEquals(50, ((UntypedDouble) locationProperties.get("floorCount")).getValue());
    assertTrue(((UntypedBoolean) locationProperties.get("hasReception")).getValue());
    assertNull((locationProperties.get("contact")).getValue());
    assertNotNull(entity.getKeywords());
    // creates untyped array
    assertInstanceOf(UntypedArray.class, entity.getKeywords());
    assertNull(entity.getDetail());
    var extra = entity.getAdditionalData().get("extra");
    assertNotNull(extra);
    assertNotNull(entity.getTable());
    // the table is a collection
    var table = (UntypedArray) entity.getTable();
    for (var value : table.getValue()) {
        var row = (UntypedArray) value;
        // The values are a nested collection
        assertNotNull(row);
        for (var item : row.getValue()) {
            var rowItem = (UntypedDouble) item;
            // The values are UntypedInteger
            assertNotNull(rowItem);
        }
    }
}

